def evaluate(expr: str) -> int:
    s = expr.replace(" ", "")
    pos = 0

    def parse_expression():
        nonlocal pos
        value = parse_term()
        while pos < len(s) and s[pos] in "+-":
            op = s[pos]
            pos += 1
            right = parse_term()
            if op == "+":
                value = value + right
            else:
                value = value - right
        return value

    def parse_term():
        nonlocal pos
        value = parse_factor()
        while pos < len(s) and s[pos] in "*/":
            op = s[pos]
            pos += 1
            right = parse_factor()
            if op == "*":
                value = value * right
            else:
                value = _trunc_div(value, right)
        return value

    def parse_factor():
        nonlocal pos
        if pos < len(s) and s[pos] == "(":
            pos += 1
            value = parse_expression()
            if pos < len(s) and s[pos] == ")":
                pos += 1
            return value
        start = pos
        while pos < len(s) and s[pos].isdigit():
            pos += 1
        return int(s[start:pos])

    def _trunc_div(a, b):
        q = abs(a) // abs(b)
        return q if (a >= 0) == (b >= 0) else -q

    return parse_expression()
