def calc(expr: str) -> int:
    s = expr.replace(" ", "").replace("\t", "").replace("\n", "")
    pos = 0

    def peek():
        return s[pos] if pos < len(s) else None

    def advance():
        nonlocal pos
        ch = s[pos]
        pos += 1
        return ch

    def parse_expr():
        # additive: + and -, left-associative
        value = parse_term()
        while peek() in ("+", "-"):
            op = advance()
            rhs = parse_term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def parse_term():
        # multiplicative: * and /, left-associative
        value = parse_unary()
        while peek() in ("*", "/"):
            op = advance()
            rhs = parse_unary()
            if op == "*":
                value = value * rhs
            else:
                if rhs == 0:
                    raise ZeroDivisionError("division by zero")
                q = abs(value) // abs(rhs)
                value = q if (value >= 0) == (rhs > 0) else -q
        return value

    def parse_unary():
        # unary minus binds looser than ^, so -2^2 == -(2^2)
        if peek() == "-":
            advance()
            return -parse_unary()
        if peek() == "+":
            advance()
            return parse_unary()
        return parse_power()

    def parse_power():
        # ^ is right-associative: 2^3^2 == 2^(3^2)
        base = parse_primary()
        if peek() == "^":
            advance()
            exp = parse_unary()  # allow unary minus in exponent position
            if exp < 0:
                raise ValueError("negative exponents are not supported")
            return base ** exp
        return base

    def parse_primary():
        ch = peek()
        if ch == "(":
            advance()
            value = parse_expr()
            if peek() != ")":
                raise ValueError("expected ')'")
            advance()
            return value
        start = pos
        while peek() is not None and peek().isdigit():
            advance()
        if start == pos:
            raise ValueError(f"unexpected character at position {pos}: {ch!r}")
        return int(s[start:pos])

    result = parse_expr()
    if pos != len(s):
        raise ValueError(f"unexpected character at position {pos}: {s[pos]!r}")
    return result
