def int_to_words(n: int) -> str:
    if n == 0:
        return "zero"

    ones = [
        "", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
        "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen",
        "seventeen", "eighteen", "nineteen",
    ]
    tens = [
        "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety",
    ]

    def below_thousand(num: int) -> str:
        parts = []
        hundreds = num // 100
        rest = num % 100
        if hundreds:
            parts.append(ones[hundreds])
            parts.append("hundred")
        if rest:
            if rest < 20:
                parts.append(ones[rest])
            else:
                t, o = divmod(rest, 10)
                if o:
                    parts.append(f"{tens[t]}-{ones[o]}")
                else:
                    parts.append(tens[t])
        return " ".join(parts)

    scales = ["", "thousand", "million"]
    groups = []
    scale_index = 0
    while n > 0:
        chunk = n % 1000
        if chunk:
            words = below_thousand(chunk)
            if scales[scale_index]:
                words = f"{words} {scales[scale_index]}"
            groups.append(words)
        n //= 1000
        scale_index += 1

    return " ".join(reversed(groups))
