def flatten_json(obj: dict) -> dict:
    result = {}

    def _flatten(value, path):
        if isinstance(value, dict):
            if not value:
                if path:
                    result[path] = value
                return
            for key, item in value.items():
                key_str = str(key)
                new_path = f"{path}.{key_str}" if path else key_str
                _flatten(item, new_path)
        elif isinstance(value, list):
            if not value:
                if path:
                    result[path] = value
                return
            for index, item in enumerate(value):
                new_path = f"{path}.{index}" if path else str(index)
                _flatten(item, new_path)
        else:
            result[path] = value

    _flatten(obj, "")
    return result
