def glob_match(name: str, pattern: str) -> bool:
    def match_class(ch: str, pat: str, i: int):
        # pat[i] == '['; returns (matched, next_index) or None if malformed
        j = i + 1
        negate = False
        if j < len(pat) and pat[j] == '!':
            negate = True
            j += 1
        first = True
        matched = False
        while j < len(pat) and (pat[j] != ']' or first):
            first = False
            if j + 2 < len(pat) and pat[j + 1] == '-' and pat[j + 2] != ']':
                lo, hi = pat[j], pat[j + 2]
                if lo <= ch <= hi:
                    matched = True
                j += 3
            else:
                if pat[j] == ch:
                    matched = True
                j += 1
        if j >= len(pat):
            return None  # unterminated bracket
        return (matched != negate, j + 1)

    def helper(ni: int, pi: int) -> bool:
        # Iterative-style memo-free recursion with backtracking on '*'
        while pi < len(pattern):
            pc = pattern[pi]
            if pc == '*':
                # Collapse consecutive stars
                while pi < len(pattern) and pattern[pi] == '*':
                    pi += 1
                if pi == len(pattern):
                    return True
                for k in range(ni, len(name) + 1):
                    if helper(k, pi):
                        return True
                return False
            if ni >= len(name):
                return False
            if pc == '?':
                ni += 1
                pi += 1
            elif pc == '[':
                result = match_class(name[ni], pattern, pi)
                if result is None:
                    # Malformed bracket: treat '[' as a literal character
                    if name[ni] != '[':
                        return False
                    ni += 1
                    pi += 1
                else:
                    matched, pi = result
                    if not matched:
                        return False
                    ni += 1
            else:
                if name[ni] != pc:
                    return False
                ni += 1
                pi += 1
        return ni == len(name)

    return helper(0, 0)
