def parse_csv_line(line: str) -> list[str]:
    fields: list[str] = []
    current: list[str] = []
    i = 0
    n = len(line)
    in_quotes = False
    field_started_quoted = False

    while i < n:
        ch = line[i]
        if in_quotes:
            if ch == '"':
                if i + 1 < n and line[i + 1] == '"':
                    current.append('"')
                    i += 2
                    continue
                in_quotes = False
            else:
                current.append(ch)
        else:
            if ch == '"' and not current and not field_started_quoted:
                in_quotes = True
                field_started_quoted = True
            elif ch == ',':
                fields.append(''.join(current))
                current = []
                field_started_quoted = False
            else:
                current.append(ch)
        i += 1

    fields.append(''.join(current))
    return fields
